/* Nature Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Nature Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 37.5 45.85% 95.36%;
    --foreground: 8.77 30.8% 19.09%;
    --card: 37.5 45.85% 95.36%;
    --card-foreground: 8.77 30.8% 19.09%;
    --popover: 37.5 45.85% 95.36%;
    --popover-foreground: 8.77 30.8% 19.09%;
    --primary: 122.69 43.81% 33.65%;
    --primary-foreground: 300 50% 100%;
    --secondary: 124.6 40.11% 93.94%;
    --secondary-foreground: 124.98 58.54% 23.69%;
    --muted: 33.73 26.25% 91.6%;
    --muted-foreground: 15 25.98% 34.17%;
    --accent: 121.99 38.82% 84.94%;
    --accent-foreground: 124.98 58.54% 23.69%;
    --destructive: 0.49 64.58% 46.96%;
    --destructive-foreground: 300 50% 100%;
    --border: 33.91 26% 83.31%;
    --input: 33.91 26% 83.31%;
    --ring: 122.69 43.81% 33.65%;
    --chart-1: 122.32 38.76% 49.09%;
    --chart-2: 122.33 40.32% 39.94%;
    --chart-3: 122.69 43.81% 33.65%;
    --chart-4: 124.98 58.54% 23.69%;
    --chart-5: 126.44 57.72% 8.08%;
    --radius: 0.5rem;
    --sidebar: 33.73 26.25% 91.6%;
    --sidebar-foreground: 8.77 30.8% 19.09%;
    --sidebar-primary: 122.69 43.81% 33.65%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 121.99 38.82% 84.94%;
    --sidebar-accent-foreground: 124.98 58.54% 23.69%;
    --sidebar-border: 33.91 26% 83.31%;
    --sidebar-ring: 122.69 43.81% 33.65%;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Merriweather, serif;
    --font-mono: Source Code Pro, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 133.11 21.59% 13.77%;
    --foreground: 32.73 26.64% 91.65%;
    --card: 124.86 14.32% 19.8%;
    --card-foreground: 32.73 26.64% 91.65%;
    --popover: 124.86 14.32% 19.8%;
    --popover-foreground: 32.73 26.64% 91.65%;
    --primary: 122.32 38.76% 49.09%;
    --primary-foreground: 126.44 57.72% 8.08%;
    --secondary: 115.49 11.12% 25.89%;
    --secondary-foreground: 114.03 17.06% 86.11%;
    --muted: 124.86 14.32% 19.8%;
    --muted-foreground: 34.75 22.17% 80.7%;
    --accent: 122.33 40.32% 39.94%;
    --accent-foreground: 32.73 26.64% 91.65%;
    --destructive: 0.49 64.58% 46.96%;
    --destructive-foreground: 32.73 26.64% 91.65%;
    --border: 115.49 11.12% 25.89%;
    --input: 115.49 11.12% 25.89%;
    --ring: 122.32 38.76% 49.09%;
    --chart-1: 122.64 39.63% 64.66%;
    --chart-2: 122.73 38.21% 57%;
    --chart-3: 122.32 38.76% 49.09%;
    --chart-4: 122.26 38.89% 45.1%;
    --chart-5: 122.33 40.32% 39.94%;
    --radius: 0.5rem;
    --sidebar: 133.11 21.59% 13.77%;
    --sidebar-foreground: 32.73 26.64% 91.65%;
    --sidebar-primary: 122.32 38.76% 49.09%;
    --sidebar-primary-foreground: 126.44 57.72% 8.08%;
    --sidebar-accent: 122.33 40.32% 39.94%;
    --sidebar-accent-foreground: 32.73 26.64% 91.65%;
    --sidebar-border: 115.49 11.12% 25.89%;
    --sidebar-ring: 122.32 38.76% 49.09%;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Merriweather, serif;
    --font-mono: Source Code Pro, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
